/********************************************** 
 * 설명       : 직전영업일 가져옴
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 설명       : 수입/환급결의조회
 ***********************************************/
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_IMPORT_REFND_LIST";
    url += "&queryId=lds.stf.bnsimport_refnd.select.list";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CHK_1=" + scwin.getChkValue(chb_View1);
    url += "&{P}V_CHK_2=" + scwin.getChkValue(chb_View2);
    url += "&{P}V_CHK_3=" + scwin.getChkValue(chb_View3);
    url += "&{P}V_CHK_4=" + scwin.getChkValue(chb_View4);
    url += "&{P}V_CHK_5=" + scwin.getChkValue(chb_View5);
    url += "&{P}V_CHK_6=" + scwin.getChkValue(chb_View6);
    url += "&{P}V_CHK_7=" + scwin.getChkValue(chb_View7);
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_EDate);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.getChkValue = function(obj) {
    return (obj.checked) ? "Y" : "N";
};
scwin.fn_CheckAll = function() {
    chb_View1.setValue(chb_ViewAll.checked);
    chb_View2.setValue(chb_ViewAll.checked);
    chb_View3.setValue(chb_ViewAll.checked);
    chb_View4.setValue(chb_ViewAll.checked);
    chb_View5.setValue(chb_ViewAll.checked);
    chb_View6.setValue(chb_ViewAll.checked);
    chb_View7.setValue(chb_ViewAll.checked);
};
scwin.gform_onload = function() {
    /********************************************** 
     * Event   : gform > onload
     * 설명    : 화면 OnLoad
     ***********************************************/

    $c.bns.BnsPanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    edt_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    scwin.fn_CheckAll();
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * Event   : btn_Search > onclick
     * 설명    : 조회버튼 클릭
     ***********************************************/
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    /********************************************** 
     * Event   : btn_Excel > onclick
     * 설명    : 엑셀버튼 클릭
     ***********************************************/
    //엑셀 로그 
    //doLogSave(vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_수입환급결의조회.xls";
    $c.data.downloadGridViewExcel(grd_List, "수입환급결의조회", "", "8");
};
scwin.dts_List_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List > OnLoadError
     * 설명    : 데이터셋 onLoad실패
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_List > OnLoadCompleted
     * 설명    : 데이터셋 onLoad성공
     ***********************************************/
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
    if (rowcount < 1) {
        tbx_Tot_Sum.innerText = "";
    } else {
        var vsTotSum = 0;
        for (var i = 1; i <= rowcount; i++) {
            vsTotSum += Number(dts_List.getCellData(i, "DEFCT_AMT").replace(/,/g, ""));
        }
        vsTotSum = vsTotSum + "";
        for (var i = vsTotSum.length - 3; i >= 0; i--) {
            if (!((i == 1) && (vsTotSum.substring(0, 1) == "-"))) {
                vsTotSum = vsTotSum.substring(0, i) + "," + vsTotSum.substring(i, vsTotSum.length);
            }
            i = i - 2;
        }
        if (vsTotSum.substring(0, 1) == "-") {
            if (vsTotSum.substring(1, 2) == ",") {
                vsTotSum = "-" + vsTotSum.substring(2, vsTotSum.length);
            }
        } else if (vsTotSum.substring(0, 1) == ",") {
            vsTotSum = vsTotSum.substring(1, vsTotSum.length);
        }
        tbx_Tot_Sum.setValue(vsTotSum);
    }
};
scwin.img_SDate_onclick = function() {
    /********************************************** 
     * Event   : img_SDate > onclick
     * 설명    : 시작일자 달력 클릭
     ***********************************************/
    popUpCalendar2(edt_SDate);
};
scwin.img_EDate_onclick = function() {
    /********************************************** 
     * Event   : img_EDate > onclick
     * 설명    : 종료일자 달력 클릭
     ***********************************************/
    popUpCalendar2(edt_EDate);
};
scwin.chb_ViewAll_onclick = function() {
    /********************************************** 
     * Event   : chb_ViewAll > onclick
     * 설명    : 체크박스 전체 선택
     ***********************************************/
    scwin.fn_CheckAll();
};
